//
//  LakeGeneratedBindings.swift
//  Sector — Lake Brain: the generated, MACHINE_VERIFIED bindings table → LakeSourceBinding
//
//  Reads `LakeSourceBindingsGenerated.json` (GENERATED by scripts/generate-lake-bindings.py from
//  jobs/lake-brain/data/bindings.proposed.v1.json) and turns each record into a binding.
//
//  THE GATE: a record is `.candidate` unless its lakeId is in the accepted batch
//  (jobs/lake-brain/data/accepted_batch.json, embedded as `acceptedLakeIds`), in which case it is
//  `.reviewed`. A `.candidate` never publishes a state: the runner, the planner and the classifier
//  all require `.reviewed`. `make(records:accepted:)` is the only place the status is decided.
//

import Foundation

public enum LakeGeneratedBindings {

    // MARK: record (compact table row)

    struct Record: Decodable {
        struct Live: Decodable {
            var provider: String
            var capability: String
            var station: String
            var series: String?
            var cadenceMin: Int
            var lagMin: Int
            var datumOffsetFt: Double?
            var note: String?
        }
        struct Hist: Decodable {
            var kind: String
            var locationId: String?
            var office: String?
            var series: String?
            var site: String?
            var param: String?
            var stat: String?
            var offsetFt: Double?
            var item: String?
            var lid: String?
            var pe: String?
        }
        struct Level: Decodable {
            var role: String
            var name: String
            var kind: String
            var valueFt: Double?
            var office: String?
            var location: String?
            var id: String?
            var source: String
            var seasonal: Bool
        }
        struct Plan: Decodable {
            var planSource: String
            var matchedProject: String?
            var matchBasis: String?
            var verifiedMatch: Bool
            var tvaOperatingGuide: String?
            var levels: [Level]
        }
        struct Dam: Decodable {
            var nidId: String?
            var damName: String?
            var operatorName: String?
            var hydropower: Bool?
            var floodControl: Bool?
            var source: String?
        }
        struct Verification: Decodable {
            var criteriaVersion: String
            var researchStatus: String
            var wave: String
            var checksPassed: String
            var probedAt: String
            var lastObservationAt: String?
            var ageHours: Double?
        }
        var lakeId: String
        var capability: String
        var timeZone: String
        var live: [Live]
        var history: [Hist]
        var historyCompleteYears: Int
        var historyClass: String
        var plan: Plan?
        var dam: Dam?
        var context: LakeContextFeatures?
        var verification: Verification
    }

    // MARK: load

    /// Why a table row could not be turned into a binding (empty when the table is healthy). Tests assert it is empty.
    public private(set) static var loadErrors: [String] = []

    static let records: [Record] = {
        do {
            return try JSONDecoder().decode([Record].self, from: Data(LakeSourceBindingsGenerated.json.utf8))
        } catch {
            loadErrors.append("table decode failed: \(error)")
            return []
        }
    }()

    public static let acceptedLakeIds: Set<String> = Set(LakeSourceBindingsGenerated.acceptedLakeIds)

    /// Part of `LakeSourceBindings.version`: empty for an empty batch.
    public static let versionSuffix: String = acceptedLakeIds.isEmpty ? "" : "+accepted.\(acceptedLakeIds.count).\(LakeSourceBindingsGenerated.acceptedFingerprint)"

    public static let bindings: [LakeSourceBinding] = make(records: records, accepted: acceptedLakeIds,
                                                           reviewedAt: LakeSourceBindingsGenerated.acceptedReviewedAt)

    /// Number of rows in the table (the Python table's count).
    public static var tableCount: Int { records.count }

    static func context(for lakeId: String) -> LakeContextFeatures? {
        records.first { $0.lakeId == lakeId }?.context
    }

    // MARK: record → binding

    /// Status is decided HERE and nowhere else: `.reviewed` iff the lakeId is in `accepted`.
    static func make(records: [Record], accepted: Set<String>, reviewedAt: String? = nil) -> [LakeSourceBinding] {
        records.compactMap { r in
            guard let b = binding(r, accepted: accepted.contains(r.lakeId), reviewedAt: reviewedAt) else {
                loadErrors.append("\(r.lakeId): unmappable record")
                return nil
            }
            return b
        }
    }

    static func ref(_ l: Record.Live) -> LevelSeriesRef? {
        guard let p = LevelSeriesRef.Provider(rawValue: l.provider), let c = LevelSourceCapability(rawValue: l.capability) else { return nil }
        return LevelSeriesRef(provider: p, capability: c, station: l.station, series: l.series, cadenceMin: l.cadenceMin,
                              lagMin: l.lagMin, datumOffsetFt: l.datumOffsetFt ?? 0, note: l.note)
    }

    static func history(_ h: Record.Hist) -> LakeHistorySource? {
        switch h.kind {
        case "tvaOperatingGuide": return h.locationId.map { .tvaOperatingGuide(locationId: $0) }
        case "cwmsDaily":
            guard let o = h.office, let s = h.series else { return nil }
            return .cwmsDaily(office: o, series: s)
        case "usgsDaily":
            guard let site = h.site, let p = h.param, let st = h.stat else { return nil }
            return .usgsDaily(site: site, param: p, stat: st, offsetFt: h.offsetFt ?? 0)
        case "riseDaily": return h.item.map { .riseDaily(item: $0) }
        case "hadsDaily":
            guard let l = h.lid, let pe = h.pe else { return nil }
            return .hadsDaily(lid: l, pe: pe, offsetFt: h.offsetFt ?? 0)
        default: return nil
        }
    }

    static func level(_ l: Record.Level) -> OperatorLevelRef? {
        guard let k = OperatorLevelRef.Kind(rawValue: l.kind) else { return nil }
        if k == .staticFt, l.valueFt == nil { return nil }
        return OperatorLevelRef(kind: k, name: l.name, ft: l.valueFt, office: l.office, location: l.location, id: l.id,
                                source: l.source, seasonal: l.seasonal)
    }

    static func guide(_ p: Record.Plan?) -> LakeGuideSource? {
        guard let p, p.verifiedMatch else { return nil }
        if let loc = p.tvaOperatingGuide { return .tvaOperatingGuide(locationId: loc) }
        var o = OperatorLevels(matchedProject: p.matchedProject, matchBasis: p.matchBasis, verifiedMatch: true)
        for l in p.levels {
            guard let ref = level(l) else { continue }
            switch l.role {
            case "guideCurve": o.guide = ref
            case "zoneTop": o.zoneTop = ref
            case "zoneBottom": o.zoneBottom = ref
            case "floodPoolBottom": o.floodPoolBottom = ref
            default: break
            }
        }
        if !o.hasZone { o.zoneTop = nil; o.zoneBottom = nil }   // a zone needs both edges
        return o.all.isEmpty ? nil : .operatorLevels(o)
    }

    static func binding(_ r: Record, accepted: Bool, reviewedAt: String?) -> LakeSourceBinding? {
        guard let cap = LevelSourceCapability(rawValue: r.capability) else { return nil }
        let live = r.live.compactMap(ref)
        guard live.count == r.live.count, !live.isEmpty else { return nil }
        let hist = r.history.compactMap(history)
        guard hist.count == r.history.count else { return nil }
        let v = r.verification
        let machine = MachineVerification(criteriaVersion: v.criteriaVersion, researchStatus: v.researchStatus, wave: v.wave,
                                          checksPassed: v.checksPassed, probedAt: v.probedAt, lastObservationAt: v.lastObservationAt,
                                          ageHours: v.ageHours, historyCompleteYears: r.historyCompleteYears, historyClass: r.historyClass)
        let status: LevelBindingStatus = accepted ? .reviewed : .candidate
        let base = "MACHINE_VERIFIED under \(v.criteriaVersion) (wave \(v.wave), \(v.researchStatus); checks \(v.checksPassed); probed \(v.probedAt))."
        let gate = accepted ? " Accepted in accepted_batch.json." : " NOT REVIEWED: a candidate never publishes a state."
        return LakeSourceBinding(
            lakeId: r.lakeId, status: status, capability: cap, live: live, history: hist, guide: guide(r.plan), datum: nil,
            timeZone: r.timeZone, damName: r.dam?.damName, riverSystem: nil, topOfGatesFt: nil,
            hydropower: r.dam?.hydropower, floodControl: r.dam?.floodControl, operatorName: r.dam?.operatorName,
            reviewedAt: accepted ? reviewedAt : nil, note: base + gate,
            nidId: r.dam?.nidId, factsSource: r.dam?.source, context: r.context, machine: machine)
    }
}
